package com.gymflex.controller;
import com.gymflex.entity.Member; import com.gymflex.service.GymService; import jakarta.validation.Valid; import org.springframework.stereotype.Controller; import org.springframework.ui.Model; import org.springframework.validation.BindingResult; import org.springframework.web.bind.annotation.*;
@Controller public class GymController {private final GymService s; public GymController(GymService s){this.s=s;} @GetMapping("/") public String home(Model m){m.addAttribute("memberCount",s.memberCount());m.addAttribute("checkInCount",s.checkInCount());m.addAttribute("expiring",s.expiring());m.addAttribute("members",s.members());return "index";} @GetMapping("/members/new") public String form(Model m){m.addAttribute("member",new Member());m.addAttribute("plans",s.plans());return "member-form";} @PostMapping("/members") public String save(@Valid @ModelAttribute Member x,BindingResult b,@RequestParam Long planId,Model m){if(b.hasErrors()){m.addAttribute("plans",s.plans());return "member-form";}try{s.register(x,planId);return "redirect:/";}catch(Exception e){m.addAttribute("plans",s.plans());m.addAttribute("error",e.getMessage());return "member-form";}} @PostMapping("/members/{id}/checkin") public String check(@PathVariable Long id,Model m){try{s.checkIn(id);}catch(Exception e){m.addAttribute("error",e.getMessage());}return home(m);} @PostMapping("/members/{id}/renew") public String renew(@PathVariable Long id,@RequestParam Long planId,Model m){try{s.renew(id,planId);}catch(Exception e){m.addAttribute("error",e.getMessage());}return home(m);}}
